'use strict';

// 2025 rate card data and zone lookup for the quote engine in quote.js.

// Destination zone by postal prefix. First match wins; longer prefixes are
// listed before shorter ones on purpose, do not reorder.
const ZONES = [
  { prefix: '985', zone: 3 },
  { prefix: '98', zone: 2 },
  { prefix: '97', zone: 2 },
  { prefix: '96', zone: 3 },
  { prefix: '9', zone: 1 },
  { prefix: '89', zone: 3 },
  { prefix: '8', zone: 2 },
  { prefix: '7', zone: 2 },
  { prefix: '6', zone: 1 },
  { prefix: '59', zone: 3 },
  { prefix: '5', zone: 1 },
  { prefix: '4', zone: 2 },
  { prefix: '3', zone: 3 },
  { prefix: '2', zone: 1 },
  { prefix: '1', zone: 1 },
  { prefix: '0', zone: 3 },
];

// Rate tables straight from the card. Index 0 is unused so zone numbers
// (1 to 3) index the arrays directly.
const STANDARD = {
  base: [0, 4.0, 5.5, 7.0],
  perKg: [0, 1.5, 2.0, 2.75],
  fuelPct: 0,
  etaDays: [0, 5, 6, 8],
};

const EXPRESS = {
  base: [0, 7.5, 9.0, 11.5],
  perKg: [0, 2.25, 3.25, 4.5],
  fuelPct: 0.08,
  etaDays: [0, 2, 3, 4],
};

const OVERNIGHT = {
  base: [0, 12.0, 15.0, 19.5],
  perKg: [0, 4.0, 5.5, 7.25],
  fuelPct: 0.08,
  etaDays: [0, 1, 1, 2],
};

const REMOTE_ZONE = 3;
const REMOTE_FEE = 2.5;
const MAX_WEIGHT_KG = 30;

function isPostal(postal) {
  return typeof postal === 'string' && /^[0-9]{5}$/.test(postal);
}

function zoneFor(postal) {
  if (!isPostal(postal)) { throw new Error('bad postal: ' + postal); }
  for (const row of ZONES) {
    if (postal.startsWith(row.prefix)) { return row.zone; }
  }
  throw new Error('no zone for postal: ' + postal);
}

module.exports = { STANDARD, EXPRESS, OVERNIGHT, REMOTE_ZONE, REMOTE_FEE, MAX_WEIGHT_KG, zoneFor };

