'use strict';

// Parcel quote engine. Rate card data and zone lookup live in rates.js.
// A quote is: the service base charge for the destination zone, plus the
// billable weight times the service per-kg rate for that zone, plus the
// fuel and remote surcharges. All amounts are rounded to cents at the end.

const { STANDARD, EXPRESS, OVERNIGHT, REMOTE_ZONE, REMOTE_FEE, MAX_WEIGHT_KG, zoneFor } = require('./rates.js');

function round2(n) {
  return Math.round(n * 100) / 100;
}

function billableWeight(weightKg) {
  if (!(weightKg > 0)) { throw new Error('bad weight: ' + weightKg); }
  if (weightKg > MAX_WEIGHT_KG) { throw new Error('over max weight: ' + weightKg); }
  return Math.max(1, Math.ceil(weightKg));
}

function fuelSurcharge(amount, table) {
  if (table.fuelPct === 0) { return 0; }
  return round2(amount * table.fuelPct);
}

function remoteSurcharge(zone) {
  if (zone === REMOTE_ZONE) { return REMOTE_FEE; }
  return 0;
}

function baseCharge(table, zone) {
  return table.base[zone];
}

function weightCharge(table, zone, w) {
  return w * table.perKg[zone];
}

function quoteStandard(postal, weightKg) {
  const zone = zoneFor(postal);
  const w = billableWeight(weightKg);
  const amount = baseCharge(STANDARD, zone) + weightCharge(STANDARD, zone, w);
  return round2(amount + fuelSurcharge(amount, STANDARD) + remoteSurcharge(zone));
}

function quoteExpress(postal, weightKg) {
  const zone = zoneFor(postal);
  const w = billableWeight(weightKg);
  const amount = baseCharge(EXPRESS, zone) + weightCharge(STANDARD, zone, w);
  return round2(amount + fuelSurcharge(amount, EXPRESS) + remoteSurcharge(zone));
}

function quoteOvernight(postal, weightKg) {
  const zone = zoneFor(postal);
  const w = billableWeight(weightKg);
  const amount = baseCharge(OVERNIGHT, zone) + weightCharge(OVERNIGHT, zone, w);
  return round2(amount + fuelSurcharge(amount, OVERNIGHT) + remoteSurcharge(zone));
}

function etaDays(service, postal) {
  const zone = zoneFor(postal);
  if (service === 'standard') { return STANDARD.etaDays[zone]; }
  if (service === 'express') { return EXPRESS.etaDays[zone]; }
  if (service === 'overnight') { return OVERNIGHT.etaDays[zone]; }
  throw new Error('unknown service: ' + service);
}

function quote(service, postal, weightKg) {
  if (service === 'standard') { return quoteStandard(postal, weightKg); }
  if (service === 'express') { return quoteExpress(postal, weightKg); }
  if (service === 'overnight') { return quoteOvernight(postal, weightKg); }
  throw new Error('unknown service: ' + service);
}

module.exports = { quote, quoteStandard, quoteExpress, quoteOvernight, etaDays, zoneFor, billableWeight };

