'use strict';
const test = require('node:test');
const assert = require('node:assert');
const q = require('./src/quote.js');

test('express matches the 2025 rate card (ticket 4821 case)', () => {
  assert.strictEqual(q.quote('express', '98052', 12), 51.84);
});

test('express matches the card in the other zones', () => {
  assert.strictEqual(q.quote('express', '10001', 1), 10.53);
  assert.strictEqual(q.quote('express', '30301', 2), 24.64);
});

test('standard quotes are unchanged', () => {
  assert.strictEqual(q.quote('standard', '98052', 12), 29.5);
  assert.strictEqual(q.quote('standard', '30301', 5), 23.25);
});

test('overnight quotes are unchanged', () => {
  assert.strictEqual(q.quote('overnight', '98052', 12), 87.48);
  assert.strictEqual(q.quote('overnight', '10001', 1), 17.28);
});

test('zone and eta lookups are unchanged', () => {
  assert.strictEqual(q.zoneFor('98052'), 2);
  assert.strictEqual(q.zoneFor('98501'), 3);
  assert.strictEqual(q.etaDays('express', '98052'), 3);
});

